  "inlineSchema": "// Hub owns this database, and it owns only Hub's own data.\n//\n// Identity is NOT here and never will be. Who someone is - employee or\n// student, their unit, job level and roles - is always asked of Central on\n// every sign-in and every launch. Central is the source of truth for people;\n// this database is the source of truth for the launcher: which apps exist,\n// who may see them, and what users have reported or requested.\n//\n// That split is also why Hub connects to its own Postgres rather than\n// Central's: Hub holds an API token scoped to employees:read and\n// students:read, so a compromise of Hub cannot reach health records, consent\n// files or employee PII. Giving Hub database credentials to Central would\n// throw that away.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// Mirrors the union in src/type/catalog-type.ts. Kept as a database enum so\n// an invalid status cannot be written by an admin screen or a bad migration.\nenum ApplicationStatus {\n  ACTIVE\n  MAINTENANCE\n  COMING_SOON\n  NEW\n}\n\nenum ReportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n}\n\nenum AccessRequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nmodel Application {\n  // The catalog id, written by hand rather than generated: it appears in\n  // launch URLs (/apps/:id/launch) and in status overrides, so it has to\n  // stay stable and readable.\n  id String @id\n\n  name        String\n  icon        String @default(\"AppWindow\")\n  description String\n  // Display copy only - who the app is for, in the school's own words.\n  // allowed_sources below is what actually decides access.\n  audience    String\n  category    String\n\n  // Invisible search fodder, so one app is findable from several angles\n  // without belonging to two categories.\n  keywords String[] @default([])\n\n  // Null means the app is registered but has no URL yet. The card shows\n  // \"no link registered\" instead of pretending it can be opened.\n  href     String?\n  external Boolean @default(true)\n\n  status       ApplicationStatus @default(ACTIVE)\n  // Display lever: false drops the app from the grid for everyone. Distinct\n  // from allowed_sources, which is the access lever.\n  discoverable Boolean           @default(true)\n\n  // Deny by default. An empty list admits nobody, which is how an app with\n  // no workable policy yet stays out of everyone's way. Values are\n  // Central-backed access keys: identity source, role keys, or \"public\".\n  allowed_sources String[] @default([])\n\n  // Set only for apps with their own /auth/sso exchange endpoint. Moving\n  // the entry URL here is what removes the per-app <APP>_API_URL env var\n  // that previously had to be deployed alongside a catalog edit.\n  sso_app_id                     String? @unique\n  sso_entry_url                  String?\n  // Optional: an app without a local session to clear just doesn't get\n  // included in Hub's logout fan-out (loaded in a hidden iframe on sign-out).\n  sso_logout_url                 String?\n  // When set, launch also requires a current active entitlement from Central.\n  sso_central_entitlement_app_id String?\n\n  sort_order Int @default(0)\n\n  created_at DateTime  @default(now())\n  updated_at DateTime  @updatedAt\n  // Soft delete, same convention as Central: an app removed from the\n  // catalog keeps its reports and requests readable.\n  deleted_at DateTime?\n\n  reports         AppReport[]\n  access_requests AccessRequest[]\n\n  @@index([category])\n  @@index([status])\n  @@index([discoverable])\n  @@index([sort_order])\n  @@map(\"applications\")\n}\n\n// Short-lived, single-use SSO handoffs. Deployments may keep using the\n// in-memory store; this table is used when SSO_CODE_STORE=postgres so codes\n// remain redeemable across Hub instances.\nmodel SsoCode {\n  code       String   @id\n  token      String\n  app_id     String\n  state      String?\n  expires_at DateTime\n  created_at DateTime @default(now())\n\n  @@index([expires_at])\n  @@map(\"sso_codes\")\n}\n\n// Requirement 9: a quick button on app cards so users can tell MAD Labs a\n// tool is not loading.\nmodel AppReport {\n  id String @id @default(cuid())\n\n  application_id String\n  application    Application @relation(fields: [application_id], references: [id])\n\n  // Email only, never a user id: Hub does not own user records, so there is\n  // nothing here to join against. Central resolves the person when needed.\n  reporter_email String\n  message        String\n\n  status      ReportStatus @default(OPEN)\n  resolved_at DateTime?\n  resolved_by String?\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@index([application_id])\n  @@index([status])\n  @@index([created_at])\n  @@map(\"app_reports\")\n}\n\n// Requirement 10: a prompt for users to ask for an app permission they are\n// missing. APPROVED rows are Hub-owned per-user grants for that app.\nmodel AccessRequest {\n  id String @id @default(cuid())\n\n  application_id String\n  application    Application @relation(fields: [application_id], references: [id])\n\n  requester_email String\n  reason          String?\n\n  status        AccessRequestStatus @default(PENDING)\n  decided_at    DateTime?\n  decided_by    String?\n  decision_note String?\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  // One open request per person per app - a second click should not create\n  // a duplicate for MAD Labs to triage.\n  @@unique([application_id, requester_email, status])\n  @@index([status])\n  @@index([created_at])\n  @@map(\"access_requests\")\n}\n\n// Admin-facing audit trail. This intentionally stores Hub admin actions, not\n// Central identity history: the actor snapshot comes from the active session\n// and the entity data points back to Hub-owned rows.\nmodel AuditLog {\n  id String @id @default(cuid())\n\n  actor_email String\n  actor_name  String?\n\n  action      String\n  entity_type String\n  entity_id   String\n  summary     String\n  metadata    Json?\n\n  created_at DateTime @default(now())\n\n  @@index([created_at])\n  @@index([actor_email])\n  @@index([entity_type, entity_id])\n  @@map(\"audit_logs\")\n}\n\n// Session bookkeeping only, not identity - bumped on every Hub login so any\n// previously-issued session JWT for that person (any other browser/device)\n// fails its next verifySession() check. See lib/session.ts.\n//\n// Keyed by Central's own Employee/Student id, not email: email is an\n// editable field in Central (see EmployeeValidation.UPDATE server-side), so\n// a row keyed by email would silently orphan itself the moment someone's\n// email changes there - the next resolveCentralIdentity() lookup, done by\n// the person's *current* email, would return a *different* Central id than\n// whatever this row was keyed on, and their old row would linger, unbumped,\n// forever matching nothing. `email` stays as a plain column for admin\n// lookups/debugging only, never the identity anchor.\nmodel UserSession {\n  central_id      String   @id\n  email           String\n  session_version Int      @default(0)\n  updated_at      DateTime @updatedAt\n\n  @@index([email])\n  @@map(\"user_sessions\")\n}\n\n// What only the Hub decides about an application Central publishes: how its card is shown. Name, address\n// and access stay in Central. A row exists only once someone changed something from the default.\nmodel ApplicationDisplay {\n  application_id String            @id\n  status         ApplicationStatus @default(ACTIVE)\n  discoverable   Boolean           @default(true)\n  keywords       String[]          @default([])\n\n  updated_at DateTime @updatedAt\n  updated_by String?\n\n  @@map(\"application_display\")\n}\n",
